import java.util.*;
import java.util.concurrent.*;

public class CosmicCats {
    private final Set<String> cats;

    public CosmicCats(Set<String> cats) {
        this.cats = Collections.unmodifiableSet(new HashSet<>(Objects.requireNonNull(cats)));
    }

    public boolean isCat(String identifier) {
        return cats.contains(identifier);
    }

    public String listCats() {
        StringBuilder sb = new StringBuilder();
        for (String cat : cats) {
            sb.append(cat).append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) throws InterruptedException {
        final CosmicCats cosmicCats = new CosmicCats(new HashSet<>(Arrays.asList("Whiskers", "Paws", "Claw")));

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<String>> futures = new ArrayList<>();

        for (int i = 0; i < 3; i++) {
            Future<String> future = executor.submit(() -> cosmicCats.isCat("Whiskers") ? "Found" : "Not Found");
            futures.add(future);
        }

        for (Future<String> future : futures) {
            System.out.println(future.get());
        }

        executor.shutdown();
    }
}

import java.util.*;
import java.util.concurrent.*;

public class CosmicCats {
    private final Set<String> cats;

    public CosmicCats(Set<String> cats) {
        this.cats = Collections.unmodifiableSet(new HashSet<>(Objects.requireNonNull(cats)));
    }

    public boolean isACat(String identifier) {
        return cats.contains(identifier);
    }

    public String listCats() {
        StringBuilder sb = new StringBuilder("[");
        cats.stream().map(cat -> sb.append(cat).append(", ")) .count();
        if (sb.length() > 1) sb.delete(sb.length() - 2, sb.length());
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        Set<String> cats = new HashSet<>(Arrays.asList("Whiskers", "Paws", "Claw"));
        CosmicCats cosmicCats = new CosmicCats(cats);

