public class StellarSprites {
    private final Set<String> sprites;

    public StellarSprites(Collection<String> spriteTags) {
        sprites = Collections.unmodifiableSet(new HashSet<>(spriteTags));
    }

    public boolean isSprite(String tag) {
        return sprites.contains(tag);
    }

    public String listSprites() {
        StringBuilder sb = new StringBuilder("[");
        Iterator<String> iterator = sprites.iterator();
        while (iterator.hasNext()) {
            sb.append(iterator.next());
            if (iterator.hasNext()) {
                sb.append(", ");
            }
        }
        sb.append(']');
        return sb.toString();
