public class ContainerDemo {
    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }

    static class ElementCount {
        private int count;

        public ElementCount(int initialCount) {
            this.count = initialCount;
        }

        public synchronized void increment(int value) {
            count += value;
        }

        public synchronized void decrement(int value) {
            if (count < value) {
                throw new InsufficientElementsException("Not enough elements to complete operation");
            }
            count -= value;
        }
    }

