            return lock.tryLock(timeout.toMillis(), TimeUnit.MILLISECONDS);
        }

        public void releaseLock() {
            lock.unlock();
        }

        public void swap(Container target, int count) throws InsufficientElementsException {
            elementCount.decrement(count);
            target.elementCount.increment(count);
        }
