class WidgetCount {
    private int count;

    public WidgetCount(int count) {
        this.count = count;
    }

    public synchronized void increase(int delta) {
        count += delta;
    }

    public synchronized void decrease(int delta) throws NotEnoughWidgetsException {
        if (count < delta) {
            throw new NotEnoughWidgetsException();
        }
        count -= delta;
    }
}

class Bin {
    private WidgetCount widgetCount;

    public Bin(int initialCount) {
        this.widgetCount = new WidgetCount(initialCount);
    }

    public void addWidgets(int count) {
        widgetCount.increase(count);
    }

    public void removeWidgets(int count) throws NotEnoughWidgetsException {
        widgetCount.decrease(count);
    }
}

class NotEnoughWidgetsException extends Exception {
    public NotEnoughWidgetsException() {
        super("Not enough widgets in the bin to complete the operation.");
    }
