    public static boolean moveWidgets(Bin sourceBin, Bin targetBin, int widgetCount, long timeout, TimeUnit timeUnit) {
        ReentrantLock sourceLock = new ReentrantLock();
        ReentrantLock targetLock = new ReentrantLock();
        for (int i = 0; i < MAX_RETRIES; i++) {
            boolean sourceAcquired = attemptLock(sourceLock, timeout, timeUnit);
            if (!sourceAcquired) return false;
            boolean targetAcquired = attemptLock(targetLock, timeout, timeUnit);
            if (targetAcquired) {
                try {
                    sourceBin.removeWidgets(widgetCount);
                    targetBin.addWidgets(widgetCount);
                    return true;
                } catch (NotEnoughWidgetsException e) {
                    throw new RuntimeException("Failed to move widgets due to not enough widgets in the source bin.", e);
                } finally {
                    sourceLock.unlock();
                    targetLock.unlock();
                }
            } else {
                sourceLock.unlock();
            }
            waitBeforeRetry(i);
        }
        return false;
    }

    private static boolean attemptLock(ReentrantLock lock, long timeout, TimeUnit timeUnit) {
        try {
            return lock.tryLock(timeout, timeUnit);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Failed to acquire the lock.", e);
