import java.util.Random;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class WidgetMover {
    static class NotEnoughWidgetsException extends Exception {}

    static class WidgetCount {
        private int count;

        public WidgetCount(int initialCount) {
            this.count = initialCount;
        }

        public void decrease(int by) throws NotEnoughWidgetsException {
            if (count < by) {
                throw new NotEnoughWidgetsException();
            }
            count -= by;
        }
    }

    static class Bin {
        private final ReentrantLock lock = new ReentrantLock();
        private WidgetCount widgetCount;

        public Bin(int initialCount) {
            this.widgetCount = new WidgetCount(initialCount);
        }

        public boolean acquireLock(long timeout, TimeUnit unit) throws InterruptedException {
            return lock.tryLock(timeout, unit);
        }

        public void releaseLock() {
            lock.unlock();
        }

        public WidgetCount getWidgetCount() {
            return widgetCount;
        }
    }

    static long calculateFixedDelayComponent(long timeout, TimeUnit unit) {
        return Math.min(timeout / 2, unit.toMillis(100)); // arbitrary value
    }

    static long calculateRandomDelayComponent() {
        Random random = new Random();
        return random.nextInt(100); // arbitrary value
    }

    public boolean move(Bin source, Bin target, int toMove, long timeout, TimeUnit unit) throws InterruptedException {
        long fixedDelay = calculateFixedDelayComponent(timeout, unit);
        long startTime = System.currentTimeMillis();

        while (System.currentTimeMillis() - startTime < unit.toMillis(timeout)) {
            if (source.acquireLock(fixedDelay, TimeUnit.MILLISECONDS) && target.acquireLock(fixedDelay, TimeUnit.MILLISECONDS)) {
                try {
                    source.getWidgetCount().decrease(toMove);
                    return true;
                } catch (NotEnoughWidgetsException e) {
                    return false;
                } finally {
                    target.releaseLock();
                    source.releaseLock();
                }
            } else {
                Thread.sleep(calculateRandomDelayComponent()); // back off
            }
        }
        return false;
    }

    public static void main(String[] args) throws InterruptedException {
        WidgetMover mover = new WidgetMover();

        Bin sourceBin = new Bin(100);
        Bin targetBin = new Bin(0);

        System.out.println(mover.move(sourceBin, targetBin, 50, 10, TimeUnit.SECONDS));
    }
}
