this.name = name;
}

@Override
public String getName() {
return name;
}

@Override
public boolean equals(Object o) {
if (this == o) return true;
if (!(o instanceof SimplePerson)) return false;
SimplePerson that = (SimplePerson) o;
return Objects.equals(name, that.name);
}

