public class Grimoire {
    enum Constellation { A, B, C }
    enum Resonance { POSITIVE, NEGATIVE }

    static class Rune {
        final Constellation constellation;
        final Resonance resonance;

        Rune(Constellation c, Resonance r) {
            this.constellation = c;
            this.resonance = r;
        }
    }

    static class Harmony {
        final Rune rune1;
        final Rune rune2;

        Harmony(Rune r1, Rune r2) {
            this.rune1 = r1;
            this.rune2 = r2;
        }
    }

    static int channelTheGrimoire(List<Rune> runes) {
        List<Harmony> harmonies = new ArrayList<>();

        Map<Constellation, List<Rune>> runesByConstellation = runes.stream().collect(Collectors.groupingBy(r -> r.constellation));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        for (List<Rune> sameConstel : runesByConstellation.values()) {
            executor.submit(() -> {
                sameConstel.stream()
                    .collect(Collectors.groupingBy(r -> r.resonance))
                    .entrySet().stream()
                    .filter(e -> e.getKey() == Resonance.POSITIVE && e.getValue().size() > 0)
                    .forEach(e1 -> {
                        sameConstel.stream()
                            .filter(r -> r.resonance == Resonance.NEGATIVE)
                            .forEach(r2 -> harmonies.add(new Harmony(e1.getValue().get(0), r2)));
