public class Grimoire {
    private final List<Harmony> harmonies = new ArrayList<>();

    public void channelTheGrimoire(List<Rune> runes) {
        runes.stream()
            .sorted(Comparator.comparing(Rune::getConstellation).thenComparing(Rune::getResonance))
            .reduce((firstRune, secondRune) -> {
                if (firstRune.getConstellation().equals(secondRune.getConstellation()) &&
                    firstRune.getResonance() != secondRune.getResonance()) {
                    harmonies.add(new Harmony(firstRune, secondRune));
                }
                return secondRune;
            });
