import java.util.concurrent.*;
import java.util.concurrent.locks.*;

class Vault {
    private final ReentrantLock lock;
    private int gold;

    public Vault(int gold) {
        this.gold = gold;
        this.lock = new ReentrantLock();
    }

    public void transferGold(Vault toVault, int amount) {
        Lock firstLock = this.lock;
        Lock secondLock = toVault.lock;
        if (System.identityHashCode(this) > System.identityHashCode(toVault)) {
            firstLock = toVault.lock;
            secondLock = this.lock;
        }

        try {
            firstLock.lock();
            try {
                secondLock.lock();
                try {
                    if (this.gold >= amount) {
                        this.gold -= amount;
                        toVault.gold += amount;
                    } else {
                        throw new InsufficientGoldException("Not enough gold in the vault: " + this);
                    }
                } finally {
                    secondLock.unlock();
                }
            } finally {
                firstLock.unlock();
            }
        } catch (InsufficientGoldException e) {
            System.out.println(e.getMessage());
        }
    }
}

class InsufficientGoldException extends RuntimeException {
    public InsufficientGoldException(String message) {
        super(message);
    }
}

