        while (true) {
            int srcHash = System.identityHashCode(this);
            int destHash = System.identityHashCode(dest);

            if (srcHash < destHash) {
                this.lock.lock();
                try {
                    dest.lock.lock();
                    try {
                        gems.reduce(n);
                        dest.gems.amount += n;
                        break;
                    } finally {
                        dest.lock.unlock();
                    }
