class GemAmount {
    private int amount;

    public GemAmount(int amount) {
        this.amount = amount;
    }

    public void reduce(int value) throws InsufficientGemsException {
        if (this.amount < value) {
            throw new InsufficientGemsException();
        }
        this.amount -= value;
    }
}

class Hoard {
    private GemAmount gems;

    public Hoard(int initialAmount) {
        this.gems = new GemAmount(initialAmount);
    }

    public void transferGems(Hoard destination, int amount) throws InsufficientGemsException {
        this.gems.reduce(amount);
        destination.gems.amount += amount;
    }
}

class InsufficientGemsException extends Exception {}

class GemTransferer implements Runnable {
    private Hoard source;
    private Hoard destination;
    private int transferAmount;

    public GemTransferer(Hoard source, Hoard destination, int transferAmount) {
        this.source = source;
        this.destination = destination;
        this.transferAmount = transferAmount;
    }

    @Override
    public void run() {
        try {
            synchronized (getMinLock(source, destination)) {
                Thread.sleep(10); // To increase chance of thread interleaving
                synchronized (getMaxLock(source, destination)) {
                    source.transferGems(destination, transferAmount);
                }
            }
        } catch (InterruptedException | InsufficientGemsException e) {}
    }

    private Object getMinLock(Hoard first, Hoard second) {
        return System.identityHashCode(first) < System.identityHashCode(second) ? first : second;
    }

    private Object getMaxLock(Hoard first, Hoard second) {
        return System.identityHashCode(first) > System.identityHashCode(second) ? first : second;
    }
}

