import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

class CrystalCarousel {
    private final AtomicIntegerArray array;
    private final int capacity;
    private final Semaphore mutex = new Semaphore(1);
    private final Semaphore emptySlots;
    private final Semaphore crystals = new Semaphore(0);
    private int head = 0, tail = 0;

    public CrystalCarousel(int capacity) {
        this.capacity = capacity;
        this.array = new AtomicIntegerArray(capacity);
        this.emptySlots = new Semaphore(capacity);
    }

    public void put(int x) throws InterruptedException {
        emptySlots.acquire();
        mutex.acquire();
        try {
            array.set(head, x);
            head = (head + 1) % capacity;
        } finally {
            mutex.release();
            crystals.release();
        }
    }

    public int take() throws InterruptedException {
        crystals.acquire();
        mutex.acquire();
        try {
            int res = array.get(tail);
            tail = (tail + 1) % capacity;
            return res;
        } finally {
            mutex.release();
            emptySlots.release();
        }
    }

    public boolean isEmpty() {
        return emptySlots.availablePermits() == capacity;
    }

    public boolean isFull() {
        return crystals.availablePermits() == capacity;
    }
}

