class ChronomanticDragonTracker {
    private Constellation<String, MutableOrb> constellations;

    public ChronomanticDragonTracker(Constellation<String, MutableOrb> initialMap) {
        this.constellations = new Constellation<>(initialMap);
    }

    private static <K,V> Constellation<K,V> deepClone(Constellation<K,V> map){
        Constellation<K, V> clone = new Constellation<>(map.size());
        for (Map.Entry<? extends K, ? extends V> entry : map.entrySet()) {
            clone.put(entry.getKey(), ((MutableOrb)entry.getValue()).copy());
        }
        return clone;
    }

    public synchronized Constellation<String, MutableOrb> getConstellations() {
