import java.util.Random;
import java.util.concurrent.*;

public class SummonChaosOrbs {
    private static final int ORB_COUNT = 5;
    private static final int THREAD_COUNT = 2;
    private static final int ITERATIONS = 10;

    private static class Orb {
        private int manaShards;

        public Orb(int manaShards) {
            this.manaShards = manaShards;
        }

        public synchronized void transferEnergyTo(Orb to, int amount) {
            this.manaShards -= amount;
            to.manaShards += amount;
        }
    }

    private static class EtherealFlux {
        public static void transferEnergy(Orb from, Orb to, int amount) {
            if (from.manaShards < amount) {
                throw new InsufficientManaException();
            }
            from.transferEnergyTo(to, amount);
        }
    }

    private static class FluxThread extends Thread {
        private final Orb[] orbs;
        private final Random random;

        public FluxThread(Orb[] orbs) {
            this.orbs = orbs;
            this.random = new Random();
        }

        @Override
        public void run() {
            for (int i = 0; i < ITERATIONS; ++i) {
                int fromIndex = random.nextInt(ORB_COUNT);
                int toIndex = random.nextInt(ORB_COUNT - 1);
                if (toIndex >= fromIndex) {
                    toIndex++;
                }
                int amount = random.nextInt((orbs[fromIndex].manaShards + 1) / 2);
                try {
                    EtherealFlux.transferEnergy(orbs[fromIndex], orbs[toIndex], amount);
                } catch (InsufficientManaException e) {
                }
            }
        }
    }

    public static void main(String[] args) {
        Orb[] orbs = new Orb[ORB_COUNT];
        for (int i = 0; i < ORB_COUNT; ++i) {
            orbs[i] = new Orb(100);
        }
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT + 1);
        for (int i = 0; i < THREAD_COUNT; ++i) {
            executor.submit(new FluxThread(orbs));
        }
        executor.shutdown();
    }
}

