import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class SummonChaosOrbs {
    private static final int ORB_COUNT = 5;
    private static final int ITERATIONS = 10;
    private static final Random RANDOM = new Random();

    public static void main(String[] args) {
        List<Orb> orbs = new ArrayList<>();
        for (int i = 0; i < ORB_COUNT; i++) {
            orbs.add(new Orb());
        }

        ExecutorService service = Executors.newFixedThreadPool(2);
        for (int i = 0; i < ITERATIONS; i++) {
            service.execute(new FluxThread(orbs));
        }
        service.shutdown();
    }

    static class Orb {
        private final AtomicInteger manaShards = new AtomicInteger();

        public void addMana(int amount) {
            manaShards.addAndGet(amount);
        }

        public int getMana() {
            return manaShards.get();
        }
    }

    static class EtherealFlux {
        public void transferEnergy(Orb from, Orb to, int amount) throws InsufficientManaException {
            synchronized (from) {
                synchronized (to) {
                    if (from.getMana() < amount) {
                        throw new InsufficientManaException();
                    } else {
                        from.addMana(-amount);
                        to.addMana(amount);
                    }
                }
            }
        }
    }

    static class FluxThread extends Thread {
        private final List<Orb> orbs;
        private final EtherealFlux flux = new EtherealFlux();

        public FluxThread(List<Orb> orbs) {
            this.orbs = orbs;
        }

        @Override
        public void run() {
            int orbIndex1 = RANDOM.nextInt(orbs.size());
            int orbIndex2 = RANDOM.nextInt(orbs.size());

            while (orbIndex1 == orbIndex2) {
                orbIndex2 = RANDOM.nextInt(orbs.size());
            }

            Orb fromOrb = orbs.get(orbIndex1);
            Orb toOrb = orbs.get(orbIndex2);

            int manaAmount = RANDOM.nextInt((fromOrb.getMana() / 2) + 1);

            try {
                flux.transferEnergy(fromOrb, toOrb, manaAmount);
            } catch (InsufficientManaException ignored) {}
        }
    }

    static class InsufficientManaException extends Exception {}
}

