public class CelestialHourglass implements Runnable {
    private boolean activated;
    private long dawnTime, duskTime;

    @Override
    synchronized public void run() {
        if (!activated) {
            activated = true;
            dawnTime = System.nanoTime();
        } else {
            duskTime = System.nanoTime();
        }
    }

    synchronized public void reset() {
        activated = false;
    }

    synchronized public long getFlow() {
        return duskTime - dawnTime;
    }

