public class BarrierTimer implements Runnable {
private boolean started;
private long startTime, endTime;

public synchronized void run() {
long t = System.nanoTime();
if (!started) {
started = true;
startTime = t;
} else {
endTime = t;
}
}

public synchronized void clear() {
started = false;
}

public synchronized long getTime() {
return endTime - startTime;
}

public synchronized double getMillisTime() {
return getTime() / 1_000_000.0;
}

public static void main(String[] args) throws InterruptedException {
final BarrierTimer timer = new BarrierTimer();

Thread starter = new Thread(() -> {
timer.run();
});

Thread stopper = new Thread(() -> {
try {
Thread.sleep(500);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
timer.run();
});

starter.start();
stopper.start();

starter.join();
stopper.join();

System.out.println("Elapsed time in nanoseconds: " + timer.getTime());
System.out.println("Elapsed time in milliseconds: " + timer.getMillisTime());

timer.clear();
}
}

