import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

class EnchantedCAS {
    private AtomicInteger value;

    public EnchantedCAS(int initialValue) {
        this.value = new AtomicInteger(initialValue);
    }

    public int compareAndSwap(int expected, int newValue) {
        int prev;
        do {
            prev = value.get();
            if (prev != expected) return prev;
        } while (!value.compareAndSet(expected, newValue));
        return prev;
    }
}

class PixieDustCounter {
    private EnchantedCAS enchantedCAS;

    public PixieDustCounter(int initialLevel) {
        this.enchantedCAS = new EnchantedCAS(initialLevel);
    }

    public int getDustLevel() {
        return enchantedCAS.value.get();
    }

    public void sprinkle() {
        while (true) {
            int current = getDustLevel();
            int next = current + 1;
            if (enchantedCAS.compareAndSwap(current, next) == current) break;
        }
    }
}

