        items.acquire();
        mutex.acquire();
        int idx = count.getAndDecrement() % capacity;
        Object x = buffer[idx];
        System.out.println("Consumed: " + x);
        mutex.release();
        emptySlots.release();
        return x;
    }

    public boolean isEmpty() {
