import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

class BoundedBuffer {
    private Object[] buffer;
    private AtomicInteger count = new AtomicInteger(0);
    private int in = 0, out = 0;
    private Semaphore mutex = new Semaphore(1), empty = new Semaphore(0), full = new Semaphore(0);

    public BoundedBuffer(int size) {
        buffer = new Object[size];
    }

    public void put(Object item) throws InterruptedException {
        empty.acquire();
        mutex.acquire();
        try {
            buffer[in] = item;
            in = (in + 1) % buffer.length;
            count.incrementAndGet();
        } finally {
            mutex.release();
            full.release();
        }
    }

    public Object take() throws InterruptedException {
        full.acquire();
        mutex.acquire();
        try {
            Object item = buffer[out];
            out = (out + 1) % buffer.length;
            count.decrementAndGet();
            return item;
        } finally {
            mutex.release();
            empty.release();
        }
    }

    public boolean isEmpty() {
        return count.get() == 0;
    }

    public boolean isFull() {
        return count.get() == buffer.length;
    }
}

public class Main {
    private static final int BUFFER_SIZE = 3;
    private static final int ITEM_COUNT = 5;

    public static void main(String[] args) {
        BoundedBuffer bb = new BoundedBuffer(BUFFER_SIZE);
        ExecutorService es = Executors.newFixedThreadPool(2);

        for (int i=0; i<ITEM_COUNT; ++i) {
            int item = i;
            if (i % 2 == 0)
                es.submit(() -> { try { bb.put(item); } catch (InterruptedException ignore) {} });
            else
                es.submit(() -> { try { System.out.println("took: " + bb.take()); } catch (InterruptedException ignore) {} });
        }

        es.shutdown();
    }
}

