private static final class OneValueCache {
private final BigInteger lastNumber;
private final BigInteger[] lastFactors;

public OneValueCache(BigInteger number, BigInteger[] factors) {
this.lastNumber = number;
this.lastFactors = (factors == null) ? null : factors.clone();
}

public BigInteger[] getFactors(BigInteger input) {
if (lastNumber == null || !lastNumber.equals(input)) {
return null;
}
