import java.util.*;
import java.util.concurrent.*;

public class Animal {
    public enum Gender { MALE, FEMALE }
    public enum Species { CAT, DOG }

    private final Species species;
    private final Gender gender;

    public Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    public Species getSpecies() { return species; }
    public Gender getGender() { return gender; }
}

class Pair {
    private final Animal first;
    private final Animal second;

    public Pair(Animal first, Animal second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public String toString() {
        return "Pair: " + first + ", " + second;
    }
}

class Ark {
    private final List<Pair> pairs = new ArrayList<>();

    public void addPair(Pair pair) {
        pairs.add(pair);
    }

    @Override
    public String toString() {
        return "Ark: " + pairs;
    }
}

public class Main {
    static int loadTheArk(List<Animal> animals) {
        Collections.sort(animals, new Comparator<Animal>() {
            @Override
            public int compare(Animal a1, Animal a2) {
                int speciesComparison = a1.getSpecies().compareTo(a2.getSpecies());
                if (speciesComparison != 0) return speciesComparison;
                else return a1.getGender().compareTo(a2.getGender()) * -1; // Multiply by -1 to reverse order
            }
        });

        int pairCount = 0;
        for (int i = 0; i < animals.size(); ) {
            if (i + 1 < animals.size() &&
                animals.get(i).getSpecies().equals(animals.get(i+1).getSpecies()) &&
                animals.get(i).getGender() != animals.get(i+1).getGender()) {
                new Ark().addPair(new Pair(animals.get(i), animals.get(i+1)));
                i += 2;
                pairCount++;
            } else {
                i++;
            }
        }
        return pairCount;
    }

