            new Animal(Animal.Species.CAT, Animal.Gender.FEMALE),
            new Animal(Animal.Species.CAT, Animal.Gender.MALE),
            new Animal(Animal.Species.DOG, Animal.Gender.FEMALE),
            new Animal(Animal.Species.DOG, Animal.Gender.MALE)
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Runnable loadTask = () -> System.out.println("Number of pairs: " + loadTheArk(animals));
        executor.submit(loadTask);
        executor.shutdown();
    }
