import java.util.concurrent.*;

public class Ark {
    enum Species { CAT, DOG }
    enum Gender { MALE, FEMALE }

    static class Animal {
        Species species;
        Gender gender;

        Animal(Species species, Gender gender) {
            this.species = species;
            this.gender = gender;
        }
    }

    static class Pair {
        private final Animal first;
        private final Animal second;

        Pair(Animal first, Animal second) {
            this.first = first;
            this.second = second;
        }
    }

    static class ArkLoader implements Runnable {
        List<Animal> animals;
        ExecutorService executor;
        int pairCount = 0;

        ArkLoader(List<Animal> animals) {
            this.animals = animals;
            this.executor = Executors.newFixedThreadPool(2);
        }

        public void run() {
            List<Animal> sortedAnimals = new ArrayList<>(animals);
            Collections.sort(sortedAnimals, Comparator.comparing(a -> a.species).thenComparing(a -> a.gender));

            for (int i = 0; i < sortedAnimals.size(); i += 2) {
