            new Animal(Species.DOG, Gender.FEMALE),
            new Animal(Species.CAT, Gender.MALE),
            new Animal(Species.CAT, Gender.FEMALE)
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.execute(() -> loadTheArk(animals));
        executor.shutdown();
    }

    private static int loadTheArk(List<Animal> animals) {
        return animals.stream()
            .sorted(Comparator.comparing(a -> a.species).thenComparing(a -> a.gender))
            .collect(Collectors.groupingBy(a -> new AbstractMap.SimpleEntry<>(a.species, a.gender)))
