class PrimeProducer extends Thread {
    private final BlockingQueue<Integer> queue;
    private int generatedPrimes;

    public PrimeProducer(BlockingQueue<Integer> queue, int generatedPrimes) {
        this.queue = queue;
        this.generatedPrimes = generatedPrimes;
    }

    @Override
    public void run() {
        try {
            while (generatedPrimes > 0 && !isInterrupted()) {
