import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

class PrimeProducer extends Thread {
    private final BlockingQueue<Integer> queue;
    private int produced = 0;
    private int nPrimes = 2;

    public PrimeProducer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            while (produced < nPrimes && !isInterrupted()) {
                int num = generateNextPrime();
                produced++;
                queue.put(num);
            }
        } catch (InterruptedException e) {
            interrupt();
        }
    }

    private int generateNextPrime() {
        return IntStream.iterate(2, i -> i + 1)
                        .filter(this::isPrime)
                        .findFirst()
                        .getAsInt();
    }

    private boolean isPrime(int n) {
        return IntStream.rangeClosed(2, (int) Math.sqrt(n))
                        .noneMatch(i -> n % i == 0);
    }
}

class PrimeConsumer extends Thread {
    private final BlockingQueue<Integer> queue;

    public PrimeConsumer(BlockingQueue<Integer> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        try {
            while (!isInterrupted()) {
                int num = queue.take();
                System.out.println("Consumed: " + num);
            }
        } catch (InterruptedException e) {
            interrupt();
        }
    }
}

