import java.util.*;
import java.util.concurrent.*;

class Node<T> {
    T data;
    List<Node<T>> children = new ArrayList<>();

    Node(T data) { this.data = data;}

    void addChild(Node<T> child) {
        children.add(child);
    }
}

class ElementProcessor {
    private ExecutorService executor;

    public ElementProcessor() {
        executor = Executors.newFixedThreadPool(2);
    }

    List<String> processSequentially(Node<String> node) {
        List<String> results = new ArrayList<>();
        processSequentiallyHelper(node, results);
        return results;
    }

    void processSequentiallyHelper(Node<String> node, List<String> results) {
        results.add(node.data);
        for (Node<String> child : node.children) {
            processSequentiallyHelper(child, results);
        }
    }

    List<String> processParallel(Node<String> node) {
        List<String> results = Collections.synchronizedList(new ArrayList<>());
        processParallelHelper(node, results);
        return results;
    }

    void processParallelHelper(Node<String> node, List<String> results) {
        results.add(node.data);

        List<Future<?>> futures = new ArrayList<>();
        for (Node<String> child : node.children) {
            Future<?> future = executor.submit(() -> processParallelHelper(child, results));
            futures.add(future);
        }

        futures.forEach(f -> {
            try {
                f.get();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }

    void shutdown() {
        executor.shutdown();
    }
}

public class Main {
    public static void main(String[] args) {
        Node<String> root = new Node<>("Root");

        root.addChild(new Node<>("A"));
        root.addChild(new Node<>("B"));

        root.children.get(0).addChild(new Node<>("1"));
        root.children.get(0).addChild(new Node<>("2"));

        root.children.get(1).addChild(new Node<>("3"));
        root.children.get(1).addChild(new Node<>("4"));

        ElementProcessor processor = new ElementProcessor();

        List<String> seqResults = processor.processSequentially(root);
        System.out.println("Sequential results: " + seqResults);

        List<String> parResults = processor.processParallel(new Node<>("NewRoot"));
        System.out.println("Parallel results: " + parResults);

        processor.shutdown();
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

class TreeNode<T> {
    T value;
    TreeNode<T> left, right;

    TreeNode(T value) {
        this.value = value;
    }

    void addLeftChild(T leftValue) {
        left = new TreeNode<>(leftValue);
    }

    void addRightChild(T rightValue) {
        right = new TreeNode<>(rightValue);
    }
}

class ElementProcessor {
    private ExecutorService executor;

    public ElementProcessor() {
        executor = Executors.newFixedThreadPool(2);
    }

    public <T> List<T> processElementsSequentially(List<TreeNode<T>> nodes, Function<TreeNode<T>, T> operation) {
        List<T> results = new ArrayList<>();
        for (TreeNode<T> node : nodes) {
            results.add(operation.apply(node));
        }
        return results;
    }

    public <T> List<T> processElementsInParallel(List<TreeNode<T>> nodes, Function<TreeNode<T>, T> operation) {
        List<Future<T>> futures = new ArrayList<>();
        for (TreeNode<T> node : nodes) {
            Future<T> result = executor.submit(() -> operation.apply(node));
            futures.add(result);
        }

        List<T> results = new ArrayList<>();
        for (Future<T> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }

        return results;
    }

    public void shutdown() {
        executor.shutdown();
    }
}

public class Main {
