import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        ExecutorService service = Executors.newFixedThreadPool(2);
        Node<Integer> root = new Node<>(1, Arrays.asList(
            new Node<>(2, Arrays.asList(
                new Node<>(3),
                new Node<>(4)
            )),
            new Node<>(5)
        ));

        List<Integer> seqResult = processSequentially(root, x -> x * 2);
        System.out.println("Seq: " + seqResult);

        List<Integer> parResult = processParallel(service, root, x -> x * 2);
        System.out.println("Par: " + parResult);

        service.shutdown();
    }

    public static <T, R> List<R> processSequentially(Node<T> node, Function<T, R> func) {
        List<R> result = new ArrayList<>();
        processSeqHelper(node, func, result);
        return result;
    }

    private static <T, R> void processSeqHelper(Node<T> node, Function<T, R> func, List<R> result) {
        result.add(func.apply(node.getValue()));
        for (Node<T> child : node.getChildren()) {
            processSeqHelper(child, func, result);
        }
    }

    public static <T, R> List<R> processParallel(ExecutorService service, Node<T> node, Function<T, R> func) {
        List<R> result = Collections.synchronizedList(new ArrayList<>());
        CompletableFuture<Void> future = processParHelper(service, node, func, result);
        future.join();
        return result;
    }

    private static <T, R> CompletableFuture<Void> processParHelper(ExecutorService service, Node<T> node, Function<T, R> func, List<R> result) {
        result.add(func.apply(node.getValue()));
        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (Node<T> child : node.getChildren()) {
            CompletableFuture<Void> future = processParHelper(service, child, func, result);
            futures.add(future);
        }
        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]));
    }
}

